# Let's just use backtracking
def solve(n):
    def backtrack(path, used):
        if len(path) == n:
            return path
        for i in range(n):
            if not used[i]:
                # check costas condition
                ok = True
                for d in range(1, len(path) + 1):
                    if len(path) - d >= 0:
                        diff = i - path[len(path) - d]
                        # check if this diff already exists for this d
                        # we need to check all previous pairs with distance d
                        for j in range(len(path) - d):
                            if path[j+d] - path[j] == diff:
                                ok = False
                                break
                    if not ok:
                        break
                if ok:
                    used[i] = True
                    res = backtrack(path + [i], used)
                    if res:
                        return res
                    used[i] = False
        return None
    return backtrack([], [False]*n)

